<template>
  <section ref="page" class="network-topology" :class="{ collapsed: !sidebarOpen }">
    <header class="topology-header">
      <div><span class="eyebrow">INFRASTRUCTURE / NETWORK</span><h1>数据中心 <span>3D 网络拓扑</span></h1><p>基于已录入设备与端口连接 · 按设备类型分层</p></div>
      <div class="summary"><span><b>{{ graph.nodes.length }}</b> 可见设备</span><span><b>{{ graph.links.length }}</b> 真实链路</span><button :disabled="loading" @click="load">{{ loading ? '加载中…' : '刷新数据' }}</button><button @click="toggleFullscreen">{{ fullscreen ? '退出全屏' : '全屏' }}</button></div>
    </header>
    <div class="workspace">
      <aside v-show="sidebarOpen" class="sidebar" aria-label="拓扑筛选与设备列表">
        <section><h2>浏览范围 <span>{{ data.nodes.length }} 台设备</span></h2>
          <label for="topology-room">机房</label><select id="topology-room" v-model="room"><option value="all">全部机房</option><option v-for="dc in data.data_centers" :key="dc.id" :value="String(dc.id)">{{ dc.name }}</option><option value="unassigned">未分配机柜</option></select>
          <p class="hint">单机房视图包含直接连接的外部设备。</p>
          <label for="topology-search">查找设备</label><input id="topology-search" v-model="search" type="search" placeholder="名称 / IP / 资产编号 / 机柜" />
        </section>
        <section><h2>设备分层 <button class="text-button" @click="tier = null">显示全部</button></h2>
          <button v-for="(item, index) in tiers" :key="item.name" class="tier-button" :class="{ active: tier === index }" :aria-pressed="tier === index" @click="tier = tier === index ? null : index">
            <span class="tier-number" :style="{ color: item.color, background: item.color + '18' }">0{{ index + 1 }}</span><span class="tier-copy"><strong>{{ item.name }}</strong><small>{{ item.description }}</small></span><span>{{ roomGraph.nodes.filter(n => tierIndex(n.device_type) === index).length }}</span>
          </button>
        </section>
        <section class="device-section"><h2>设备列表 <span>{{ matchingNodes.length }}</span></h2>
          <div class="device-list"><button v-for="node in matchingNodes" :key="node.id" class="node-button" :class="{ active: selectedId === node.id }" @click="selectedId = node.id"><i :style="{ background: tiers[tierIndex(node.device_type)].color }"></i><span><strong>{{ node.name }}</strong><small>{{ node.ip_address || node.rack_code || '未填写 IP' }}<em v-if="isExternal(node)">外部</em></small></span></button><p v-if="!matchingNodes.length" class="hint">{{ search ? '没有匹配的设备，请调整关键词。' : '当前范围没有设备。' }}</p></div>
        </section>
        <div class="sidebar-footer"><router-link to="/devices">设备管理 ↗</router-link><router-link to="/network">维护网络连接 ↗</router-link></div>
      </aside>
      <main class="stage">
        <TopologyScene ref="scene" :nodes="graph.nodes" :links="graph.links" :selected="selectedId" :labels="labels" :link-labels="linkLabelsOn" :rotate="rotate" :flow="flow" @select="selectedId = $event" />
        <div class="stage-top"><button @click="sidebarOpen = !sidebarOpen">{{ sidebarOpen ? '收起侧栏' : '展开侧栏' }}</button><span>{{ roomName }}<template v-if="tier !== null"> / {{ tiers[tier].name }}</template></span><button v-if="selectedId !== null" @click="selectedId = null">取消聚焦</button></div>
        <div v-if="error" class="stage-message error" role="alert"><strong>拓扑数据加载失败</strong><p>{{ error }}</p><button @click="load">重新加载</button></div>
        <div v-else-if="loading" class="stage-message" role="status"><strong>正在读取设备和网络连接…</strong></div>
        <div v-else-if="!graph.nodes.length" class="stage-message"><strong>{{ data.nodes.length ? '当前筛选范围暂无设备' : '还没有录入设备' }}</strong><p>{{ data.nodes.length ? '请切换机房或显示全部设备类型。' : '在设备管理中录入设备后，即可自动生成拓扑。' }}</p><router-link v-if="!data.nodes.length" to="/devices">前往设备管理 →</router-link><button v-else @click="room = 'all'; tier = null">显示全部</button></div>
        <div v-else-if="!graph.links.length" class="no-links">当前范围暂无网络连接，可在“网络上联”中录入。</div>
        <div class="stage-legend"><span v-for="(label, status) in linkLabels" :key="status"><i :style="{ borderColor: linkColors[status], borderTopStyle: status === 'up' ? 'solid' : 'dashed' }"></i>{{ label }}</span><small>状态来自平台录入</small></div>
        <aside v-if="selectedNode" class="inspector" aria-label="设备详情">
          <div class="inspector-heading"><span :style="{ color: tiers[tierIndex(selectedNode.device_type)].color }">{{ deviceTypeLabel(selectedNode.device_type) }}</span><button aria-label="关闭设备详情" @click="selectedId = null">×</button></div>
          <h2>{{ selectedNode.name }}</h2><p class="location">{{ locationLabel(selectedNode) }}<em v-if="isExternal(selectedNode)">外部设备</em></p>
          <dl><dt>状态</dt><dd>{{ deviceStatusLabel(selectedNode.status) }}</dd><dt>IP 地址</dt><dd>{{ selectedNode.ip_address || '未填写' }}</dd><dt>资产编号</dt><dd>{{ selectedNode.asset_number || '未填写' }}</dd><dt>型号</dt><dd>{{ selectedNode.model || '未填写' }}</dd><dt>U 位</dt><dd>{{ selectedNode.start_u ? `U${selectedNode.start_u}–${selectedNode.start_u + selectedNode.u_height - 1}` : '未上架' }}</dd><dt>管理员</dt><dd>{{ selectedNode.administrators.join('、') || '未填写' }}</dd></dl>
          <p v-if="selectedNode.purpose" class="purpose">{{ selectedNode.purpose }}</p><p v-if="selectedNode.notes" class="hint">备注：{{ selectedNode.notes }}</p><h3>端口连接 <span>{{ selectedLinks.length }}</span></h3><p v-if="!selectedLinks.length" class="hint">此设备尚未录入网络连接。</p>
          <button v-for="link in selectedLinks" :key="link.id" class="neighbor" @click="selectNeighbor(link)"><span><i :style="{ background: linkColors[link.status] }"></i>{{ peerNode(link)?.name || '未知设备' }}<small>{{ linkLabels[link.status] }}</small></span><small>{{ selectedPort(link) }} ↔ {{ peerPort(link) }}</small><small>{{ link.bandwidth || '带宽未填' }} · VLAN {{ link.vlan || '未填写' }}</small><small v-if="link.description">{{ link.description }}</small></button>
        </aside>
        <footer class="controls"><div><button :class="{ on: rotate }" :aria-pressed="rotate" @click="rotate = !rotate">自动旋转</button><button :class="{ on: labels }" :aria-pressed="labels" @click="labels = !labels">设备标签</button><button :class="{ on: linkLabelsOn }" :aria-pressed="linkLabelsOn" @click="linkLabelsOn = !linkLabelsOn">链路说明</button><button :class="{ on: flow }" :aria-pressed="flow" @click="flow = !flow">流动示意</button><button @click="scene?.resetView(true)">俯视</button><button @click="resetView">重置视角</button></div><p>拖动旋转 · 滚轮缩放 · 右键平移 · 点击节点查看连接<span v-if="flow"> · 动画仅为示意，不代表实时流量或方向</span></p></footer>
      </main>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import client from '../api/client'
import TopologyScene from '../components/topology/TopologyScene.vue'
import { tiers, tierIndex, linkColors, linkLabels, locationLabel, scopeGraph, type SceneData, type SceneDevice, type SceneLink } from '../components/topology/model'
import { deviceTypeLabel, deviceStatusLabel } from '../utils/labels'
const data = ref<SceneData>({ data_centers: [], nodes: [], links: [] })
const room = ref('all'), tier = ref<number | null>(null), search = ref(''), selectedId = ref<number | null>(null)
const loading = ref(true), error = ref(''), sidebarOpen = ref(true), fullscreen = ref(false)
const labels = ref(true), linkLabelsOn = ref(false), rotate = ref(false), flow = ref(false)
const page = ref<HTMLElement>(), scene = ref<InstanceType<typeof TopologyScene>>()
const roomGraph = computed(() => scopeGraph(data.value, room.value, null))
const graph = computed(() => scopeGraph(data.value, room.value, tier.value))
const nodesById = computed(() => new Map(data.value.nodes.map(node => [node.id, node])))
const matchingNodes = computed(() => { const term = search.value.trim().toLocaleLowerCase(); return graph.value.nodes.filter(n => !term || [n.name, n.ip_address, n.asset_number, n.model, locationLabel(n)].some(v => v?.toLocaleLowerCase().includes(term))) })
const selectedNode = computed(() => selectedId.value === null ? null : nodesById.value.get(selectedId.value))
const selectedLinks = computed(() => selectedId.value === null ? [] : data.value.links.filter(l => l.source === selectedId.value || l.target === selectedId.value))
const roomName = computed(() => room.value === 'all' ? '全部机房' : room.value === 'unassigned' ? '未分配机柜' : data.value.data_centers.find(dc => String(dc.id) === room.value)?.name || '机房')
const isExternal = (node: SceneDevice) => room.value !== 'all' && !roomGraph.value.local.has(node.id)
const peerId = (link: SceneLink) => link.source === selectedId.value ? link.target : link.source
const peerNode = (link: SceneLink) => nodesById.value.get(peerId(link))
const selectedPort = (link: SceneLink) => link.source === selectedId.value ? link.source_port : link.target_port
const peerPort = (link: SceneLink) => link.source === selectedId.value ? link.target_port : link.source_port
function selectNeighbor(link: SceneLink) { const id = peerId(link); if (!roomGraph.value.nodes.some(n => n.id === id)) room.value = 'all'; if (!graph.value.nodes.some(n => n.id === id)) tier.value = null; selectedId.value = id }
function resetView() { rotate.value = false; selectedId.value = null; scene.value?.resetView() }
let request: AbortController | undefined
async function load() {
  request?.abort(); const controller = new AbortController(); request = controller; loading.value = true; error.value = ''
  try { const response = await client.get<SceneData>('/visualization/network', { signal: controller.signal }); if (controller.signal.aborted) return; data.value = response.data; if (!['all', 'unassigned'].includes(room.value) && !data.value.data_centers.some(dc => String(dc.id) === room.value)) room.value = 'all' }
  catch (err: any) { if (!controller.signal.aborted) error.value = err.response?.status === 404 ? '接口尚未就绪，请重启后端服务后重试。' : '无法读取拓扑数据，请检查网络或后端服务后重试。' }
  finally { if (!controller.signal.aborted) loading.value = false }
}
async function toggleFullscreen() { try { if (document.fullscreenElement === page.value) await document.exitFullscreen(); else await page.value?.requestFullscreen() } catch { ElMessage.info('当前浏览器不支持全屏，可使用浏览器的全屏功能。') } }
function fullscreenChanged() { fullscreen.value = document.fullscreenElement === page.value }
watch(graph, value => { if (selectedId.value !== null && !value.nodes.some(node => node.id === selectedId.value)) selectedId.value = null })
onMounted(() => { load(); document.addEventListener('fullscreenchange', fullscreenChanged) })
onBeforeUnmount(() => { request?.abort(); document.removeEventListener('fullscreenchange', fullscreenChanged) })
</script>

