enter}.sidebar h2>span{font-size:10px;color:var(--tp-sub);font-weight:400}.sidebar label{display:block;font-size:11px;color:var(--tp-sub);margin:10px 0 7px}.sidebar select,.sidebar input{box-sizing:border-box;background:#091324;border:1px solid #2a3f5e;border-radius:7px;color:#d9e7ff;padding:9px 10px;width:100%;min-width:0}.sidebar option{background:#0e192c}.hint{font-size:11px;color:var(--tp-sub);line-height:1.7;margin:8px 0 0;overflow-wrap:anywhere}.network-topology .text-button{border:0;background:none;font-size:10px;padding:0;color:#8ab8fa}.network-topology .tier-button{display:flex;align-items:center;gap:9px;width:100%;padding:9px 6px;margin:3px 0;border:1px solid transparent;background:none;text-align:left}.network-topology .active{background:#1b3151!important;border-color:#4275b1!important}.tier-number{font-size:11px;border-radius:7px;padding:7px 6px}.tier-copy{flex:1;min-width:0}.tier-copy strong{display:block;font-size:12px;color:#d8e5f9;font-weight:500}.tier-copy small{display:block;margin-top:4px;font-size:9px;color:var(--tp-sub)}.device-section{flex:1;min-height:130px}.device-list{max-height:320px;overflow:auto;scrollbar-width:thin}.network-topology .node-button{width:100%;display:flex;text-align:left;gap:9px;align-items:center;border-color:transparent;background:none;padding:9px 6px}.node-button>i{width:6px;height:6px;border-radius:50%;flex-shrink:0}.node-button>span{min-width:0;flex:1}.node-button strong{display:block;font-size:11px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.node-button small{display:block;color:var(--tp-sub);font-size:10px;margin-top:4px}em{font-size:10px;font-style:normal;color:#eabd6b;margin-left:7px}.sidebar-footer{padding:14px 16px;display:flex;gap:15px;font-size:10px}.stage{position:relative;min-width:0;min-height:500px;overflow:hidden}.stage-top{position:absolute;top:16px;left:16px;right:16px;display:flex;align-items:center;gap:10px;pointer-events:none}.stage-top>*{pointer-events:auto}.stage-top>s